import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as t,o as e,af as i}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const u=JSON.parse('{"title":"CodeBuddy 上手","description":"按官方步骤把 CodeBuddy IDE、插件或 CLI 装上并完成第一次登录。命令和安装原文抄自 codebuddy.cn 文档站，不自行改写。","frontmatter":{"title":"CodeBuddy 上手","description":"按官方步骤把 CodeBuddy IDE、插件或 CLI 装上并完成第一次登录。命令和安装原文抄自 codebuddy.cn 文档站，不自行改写。","domain":"product","tags":["coding-agent"],"role":"tutorial"},"headers":[],"relativePath":"zh/products/codebuddy/codebuddy.md","filePath":"zh/products/codebuddy/codebuddy.md","lastUpdated":1787107158000}'),d={name:"zh/products/codebuddy/codebuddy.md"};function n(o,s,l,p,h,r){return e(),t("div",null,[...s[0]||(s[0]=[i(`<h1 id="codebuddy-上手" tabindex="-1">CodeBuddy 上手 <a class="header-anchor" href="#codebuddy-上手" aria-label="Permalink to &quot;CodeBuddy 上手&quot;">​</a></h1><blockquote><p>这是一份<strong>教程</strong>——按顺序读完，你会在一种形态里完成：下载或安装 → 登录 → 第一次对话。</p><p>查命令去 <a href="./codebuddy-cheatsheet.html">Cheatsheet</a>；抄场景去 <a href="./codebuddy-cookbook.html">Cookbook</a>；撞名去 <a href="./codebuddy-glossary.html">术语表</a>。</p></blockquote><p>本指南目标：把 CodeBuddy 从「听说腾讯也有个编码助手」变成「你知道该开 IDE、装插件，还是跑 <code>codebuddy</code>」。</p><h2 id="第-0-步-先选形态" tabindex="-1">第 0 步：先选形态 <a class="header-anchor" href="#第-0-步-先选形态" aria-label="Permalink to &quot;第 0 步：先选形态&quot;">​</a></h2><p>官方三种编程形态不是同一张皮。对照来自 <a href="https://cloud.tencent.com/document/product/1831/134343" target="_blank" rel="noreferrer">产品概述</a>：</p><table tabindex="0"><thead><tr><th>你现在的环境</th><th>选</th></tr></thead><tbody><tr><td>已经在用 VS Code / JetBrains / Visual Studio</td><td><strong>插件</strong></td></tr><tr><td>要从一句话需求做到原型、设计稿、可部署应用</td><td><strong>IDE</strong></td></tr><tr><td>人在终端，或要无头 / CI / 批量改仓库</td><td><strong>CLI（CodeBuddy Code）</strong></td></tr></tbody></table><p>三种形态共享同一账号额度（<a href="https://www.codebuddy.cn/docs/cli/troubleshooting" target="_blank" rel="noreferrer">故障排查</a>）。先装一种就能用。</p><p>定价页是前端渲染，本站不抄未核过的套餐数字。看 <a href="https://www.codebuddy.cn/pricing/" target="_blank" rel="noreferrer">codebuddy.cn/pricing</a>。页面描述有「限时免费个人版、限时免费企业旗舰版以及企业专享版」。</p><h2 id="安装-ide" tabindex="-1">安装 IDE <a class="header-anchor" href="#安装-ide" aria-label="Permalink to &quot;安装 IDE&quot;">​</a></h2><p>来源：<a href="https://www.codebuddy.cn/docs/ide/Getting-Started/Installation" target="_blank" rel="noreferrer">安装和登录</a>。</p><p><strong>环境要求</strong>（官方表）：</p><table tabindex="0"><thead><tr><th>操作系统</th><th>支持版本</th></tr></thead><tbody><tr><td>macOS</td><td>macOS 11 (Big Sur) 及以上</td></tr><tr><td>Windows</td><td>Windows 10 及以上（不支持 Windows 7/8/8.1）</td></tr></tbody></table><p>官方提示：不满足上述要求的系统将无法启动 CodeBuddy IDE。</p><p><strong>下载</strong>：访问 <a href="https://www.codebuddy.cn/" target="_blank" rel="noreferrer">CodeBuddy CN 官网</a> 或 <a href="https://www.codebuddy.cn/ide/" target="_blank" rel="noreferrer">IDE 落地页</a>，按处理器选择对应版本。国内版下载入口官方还写了 <a href="https://copilot.tencent.com/ide" target="_blank" rel="noreferrer">copilot.tencent.com/ide</a>；国际版 <a href="https://www.codebuddy.ai/" target="_blank" rel="noreferrer">codebuddy.ai</a>。</p><p><strong>macOS 安装</strong>：把安装包拖到 Applications。</p><p><strong>Windows 安装</strong>（官方步骤）：</p><ol><li>双击安装包。若提示只为当前用户安装，选<strong>确定</strong>。</li><li>选择<strong>我同意此协议</strong>。</li><li>选择安装位置，一直<strong>下一步</strong>。</li></ol><p><strong>个人版登录</strong>（官方）：打开 IDE → <strong>登录</strong> → 选择个人微信或手机号登录 → 回到 IDE。</p><p>企业版 / 专享版登录走「腾讯统一身份」或企业管理员下发的入口，见官方同一页。本教程不展开企业购买。</p><p>更新：点右上角<strong>账户</strong> → <strong>检查更新</strong> → 有新版本时点<strong>立即安装</strong>。</p><h2 id="安装-插件" tabindex="-1">安装 插件 <a class="header-anchor" href="#安装-插件" aria-label="Permalink to &quot;安装 插件&quot;">​</a></h2><p>来源：<a href="https://www.codebuddy.cn/docs/plugin/" target="_blank" rel="noreferrer">插件文档首页</a>。</p><p><strong>官方最低版本</strong>（文档总览与插件页；Visual Studio 一行插件页写 17.6，总览写 17.0，以插件页为准）：</p><table tabindex="0"><thead><tr><th>IDE</th><th>最低版本要求</th></tr></thead><tbody><tr><td>Visual Studio Code</td><td>1.82</td></tr><tr><td>Visual Studio</td><td>17.6（VS 2022）</td></tr><tr><td>IntelliJ IDEA / PyCharm / GoLand / CLion / PhpStorm</td><td>2022.2</td></tr><tr><td>Android Studio</td><td>Flamingo | 2022.2.1</td></tr><tr><td>微信开发者工具 IDE</td><td>1.06.2409140</td></tr></tbody></table><p>官方注意：其它 JetBrains IDE 看 JetBrains 插件市场；另有可低至 2020.3 的兼容包，但「无法体验最新的产品功能」。</p><p><strong>VS Code</strong>（官方三种装法）：</p><ol><li>安装 VS Code 1.82+。</li><li>装插件，任选其一： <ul><li>官方「一键安装」跳转（需本机已正确安装 VS Code）</li><li>在插件市场搜索 <strong>腾讯云代码助手</strong></li><li>下载安装包，在 VS Code 里手动安装</li></ul></li></ol><p><strong>JetBrains</strong>：设置 → <strong>插件</strong> → 搜索 <strong>腾讯云代码助手</strong> → <strong>安装</strong>；或「从磁盘安装插件」。</p><p><strong>登录</strong>：官方 <a href="https://www.codebuddy.cn/docs/plugin/%E5%BF%AB%E9%80%9F%E5%85%A5%E9%97%A8/%E7%99%BB%E5%BD%95%E5%8F%8A%E9%80%80%E5%87%BA" target="_blank" rel="noreferrer">登陆及退出</a> 写：单击底部 icon 或登录页触发登录。</p><p>插件能力（<a href="https://cloud.tencent.com/document/product/1831/134343" target="_blank" rel="noreferrer">产品概述</a>）：行内补全、错误修复、解释、单测、本地评审、<code>@workspace</code> / <code>#Codebase</code>、技术对话、自定义指令、RAG 知识库、混元 / DeepSeek 等模型切换。</p><p>第一次建议：打开一个你熟悉的文件，用补全写下一行；再用对话问「这个文件做什么」。工程级问题用官方提供的 <code>@workspace</code> 或 <code>#Codebase</code>，不要假设它已经记住整个公司的所有仓库。</p><h2 id="安装-cli" tabindex="-1">安装 CLI <a class="header-anchor" href="#安装-cli" aria-label="Permalink to &quot;安装 CLI&quot;">​</a></h2><p>产品名是 <strong>CodeBuddy Code</strong>，命令是 <code>codebuddy</code>，npm 包是 <code>@tencent-ai/codebuddy-code</code>。</p><p>来源：<a href="https://www.codebuddy.cn/docs/cli/installation" target="_blank" rel="noreferrer">CodeBuddy Code 安装指南</a>、<a href="https://www.codebuddy.cn/docs/cli/quickstart" target="_blank" rel="noreferrer">快速入门</a>。</p><h3 id="包管理器-推荐先走这条" tabindex="-1">包管理器（推荐先走这条） <a class="header-anchor" href="#包管理器-推荐先走这条" aria-label="Permalink to &quot;包管理器（推荐先走这条）&quot;">​</a></h3><p><strong>前置要求（安装页原文）：</strong> Node.js <strong>18.20</strong> 或更高版本。</p><p>故障排查页同样写「需要 Node.js v18.20 或更高版本」。文档总览 CLI 节写过 <code>Node.js 18.0+</code>；腾讯云国际站产品 FAQ 写过 Node.js 22+。本页以安装指南为准。</p><p>官方给出的包管理器命令：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @tencent-ai/codebuddy-code</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @tencent-ai/codebuddy-code</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @tencent-ai/codebuddy-code</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @tencent-ai/codebuddy-code</span></span></code></pre></div><p><strong>Homebrew（macOS/Linux，无需 Node.js）</strong>，安装页原文：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Tencent-CodeBuddy/tap</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> codebuddy-code</span></span></code></pre></div><p>或：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Tencent-CodeBuddy/tap/codebuddy-code</span></span></code></pre></div><p>验证（安装页原文）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codebuddy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><h3 id="原生二进制-beta" tabindex="-1">原生二进制（Beta） <a class="header-anchor" href="#原生二进制-beta" aria-label="Permalink to &quot;原生二进制（Beta）&quot;">​</a></h3><p>安装页原文：原生二进制「目前处于 Beta 测试阶段」。支持 macOS（Apple Silicon 或 Intel x86_64）、Linux（arm64 或 x86_64）、Windows（x86_64）。</p><p>从 npm 迁移：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codebuddy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p>全新安装（<strong>安装页</strong>）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://www.codebuddy.cn/cli/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span></code></pre></div><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">irm https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">www.codebuddy.cn</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cli</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">install.ps1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> iex</span></span></code></pre></div><p><a href="https://www.codebuddy.cn/docs/cli/quickstart" target="_blank" rel="noreferrer">快速入门</a> 写的是另一对官方 URL：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://copilot.tencent.com/cli/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span></code></pre></div><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">irm https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">copilot.tencent.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cli</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">install.ps1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> iex</span></span></code></pre></div><p>两页都是官方。不要合成一条。优先跟你正在读的那一页走。</p><p>命令找不到时，安装页要求把路径加入 <code>PATH</code>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/.local/bin:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PATH</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>Windows：<code>%USERPROFILE%\\AppData\\Local\\codebuddy\\bin</code>。</p><p>Windows 平台故障排查还要求安装 <strong>Git Bash</strong>（<a href="https://www.codebuddy.cn/docs/cli/troubleshooting" target="_blank" rel="noreferrer">troubleshooting</a>）。</p><p>更新：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codebuddy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span></code></pre></div><p>或再跑一遍对应的包管理器安装命令。关闭自动更新：<code>export DISABLE_AUTOUPDATER=1</code>。</p><p>配置目录默认 <code>~/.codebuddy</code>（Windows <code>%USERPROFILE%\\.codebuddy</code>），可用 <code>CODEBUDDY_CONFIG_DIR</code> 改位置。安装页写：与其它使用 CodeBuddy 引擎的应用（如 WorkBuddy）共存时，用这个变量避免配置冲突。</p><h2 id="登录-cli" tabindex="-1">登录 CLI <a class="header-anchor" href="#登录-cli" aria-label="Permalink to &quot;登录 CLI&quot;">​</a></h2><p>来源：<a href="https://www.codebuddy.cn/docs/cli/quickstart" target="_blank" rel="noreferrer">快速入门 · 登录认证</a>。</p><p>启动后选择：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Select login method:</span></span>
<span class="line"><span>› Log in via Chinese Site</span></span>
<span class="line"><span>  Log in via International Site</span></span>
<span class="line"><span>  Log in via Enterprise Domain</span></span>
<span class="line"><span>  Log in via iOA (Tencent only)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>登录方式</th><th>适用场景</th><th>说明</th></tr></thead><tbody><tr><td><strong>Chinese Site</strong></td><td>国内用户</td><td>通过腾讯云国内站 (copilot.tencent.com) 认证</td></tr><tr><td><strong>International Site</strong></td><td>海外用户</td><td>通过腾讯云国际站 (codebuddy.ai) 认证</td></tr><tr><td><strong>Enterprise Domain</strong></td><td>专享版 / 私有化</td><td>需要企业提供的服务地址</td></tr><tr><td><strong>iOA</strong></td><td>腾讯内部员工</td><td>仅限腾讯内部</td></tr></tbody></table><p><code>↑↓</code> 选择，<code>Enter</code> 后打开浏览器完成认证。</p><h2 id="第一次跑-cli" tabindex="-1">第一次跑 CLI <a class="header-anchor" href="#第一次跑-cli" aria-label="Permalink to &quot;第一次跑 CLI&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/your/project</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codebuddy</span></span></code></pre></div><p>官方强烈建议先：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&gt; /init</span></span></code></pre></div><p><a href="https://www.codebuddy.cn/docs/cli/quickstart" target="_blank" rel="noreferrer">快速入门</a> 把 <code>/init</code> 写成「强烈推荐」：预先构建项目知识图谱，后续少重复扫描。项目结构大变时：<code>/clear</code> 再 <code>/init</code>。</p><p>然后可以问：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&gt; 帮我分析这个项目的结构</span></span></code></pre></div><p>语言：启动后 <code>/config</code> 可设 Language。</p><p>单次命令（官方示例）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codebuddy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;优化这个 SQL 查询的性能&quot;</span></span></code></pre></div><p>需要碰文件或跑命令时，官方要求带 <code>-y</code> 或 <code>--dangerously-skip-permissions</code>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codebuddy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;审查 src/utils.js 的代码质量&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span></span></code></pre></div><p>权限模式用 <code>Shift+Tab</code> 切换（Windows 也支持 <code>Alt+M</code>）：官方快速开始写的顺序是 <code>default → bypass → accept → plan</code>。<code>--permission-mode</code> 的合法值见 <a href="https://www.codebuddy.cn/docs/cli/cli-reference" target="_blank" rel="noreferrer">CLI 参考</a>：<code>default</code>、<code>acceptEdits</code>、<code>auto</code>、<code>dontAsk</code>、<code>plan</code>、<code>bypassPermissions</code>。键位缩写和 flag 全名不要混着用错。</p><p>完整命令表见 <a href="./codebuddy-cheatsheet.html">Cheatsheet</a>。</p><h2 id="第-4-步-把重复约定写下来" tabindex="-1">第 4 步：把重复约定写下来 <a class="header-anchor" href="#第-4-步-把重复约定写下来" aria-label="Permalink to &quot;第 4 步：把重复约定写下来&quot;">​</a></h2><p>CLI 故障排查把 <code>CLAUDE.md</code> → <code>CODEBUDDY.md</code> 列为可迁移的「AI 指令和记忆文档」。用户级文件在 <code>~/.codebuddy/CODEBUDDY.md</code>。项目级约定放哪、官方是否保证自动读取仓库根的 <code>CODEBUDDY.md</code>，以你本机 <code>/config</code> 和官方「记忆」页为准，不要猜路径。</p><p>从 Claude Code 迁过来的推荐做法（官方「方案一：符号链接」）见 <a href="./codebuddy-cookbook.html#从-claude-code-迁移">Cookbook</a>。</p><h2 id="护栏" tabindex="-1">护栏 <a class="header-anchor" href="#护栏" aria-label="Permalink to &quot;护栏&quot;">​</a></h2><ul><li><strong>安装命令只抄官方页</strong>。npm 包名是 <code>@tencent-ai/codebuddy-code</code>，不是猜出来的 <code>@tencent/codebuddy</code>。</li><li><strong>原生安装有两套官方 URL</strong>（<code>codebuddy.cn/cli</code> 与 <code>copilot.tencent.com/cli</code>）。不要自行发明第三套。</li><li><strong><code>-p</code> 不是「自动允许一切」的同义词</strong>。碰文件 / 跑命令必须另有权限策略（<code>-y</code>、<code>--permission-mode</code> 等）。</li><li><strong>不要把 WorkBuddy、元宝、混元当成本教程的下一步</strong>。它们在 <a href="./">地图</a> 各占一行。</li><li><strong>不要对官网「提升编码效率 90%」这类句子做二次发挥</strong>。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>场景配方：<a href="./codebuddy-cookbook.html">Cookbook</a></li><li>命令与键位：<a href="./codebuddy-cheatsheet.html">Cheatsheet</a></li><li>概念：<a href="./codebuddy-glossary.html">术语表</a></li><li>官方 CLI 进阶：<a href="https://www.codebuddy.cn/docs/cli/" target="_blank" rel="noreferrer">常见工作流</a>（文档树「入门指南」）</li></ul>`,94)])])}const y=a(d,[["render",n]]);export{u as __pageData,y as default};
